async function copyText(value,button){const original=button.textContent;try{await navigator.clipboard.writeText(value);button.textContent='已复制';document.getElementById('feedback').textContent='已复制，可粘贴到地图或备忘录。';setTimeout(()=>button.textContent=original,2000);}catch{const box=document.createElement('textarea');box.value=value;box.setAttribute('aria-label','请手动复制');button.parentElement.after(box);box.focus();box.select();document.getElementById('feedback').textContent='自动复制不可用，请复制已选中的文字。';}}
document.querySelectorAll('[data-copy]').forEach(b=>b.addEventListener('click',()=>copyText(b.dataset.copy,b)));
document.querySelectorAll('[data-map]').forEach(b=>b.addEventListener('click',()=>{const q=b.dataset.map;const frame=document.getElementById('trip-map');frame.src='https://maps.google.com/maps?q='+encodeURIComponent(q)+'&output=embed';frame.title='旅行地点地图：'+q;document.getElementById('map-label').textContent='当前地点：'+q;document.getElementById('map').scrollIntoView({behavior:'smooth'});}));
document.getElementById('copy-page').addEventListener('click',e=>copyText(location.origin+location.pathname,e.currentTarget));
document.getElementById('print-page').addEventListener('click',()=>{document.querySelectorAll('details').forEach(d=>d.open=true);window.print();});
